// The game's messages in Live: each line the engine prints is logged and drawn in the message panels, and the
// ones that name a moment start its picture (a dig, a prayer, a fountain's wish, a trap going off, a first kill...).
// Moved out of live.js unchanged; it reads the game's state and helpers from L (installLive's shared names).
import {takerOf,takenSquares} from './held-items.js';
import {petEats} from './feline-mind.js';
import {isThronePuff} from './throne-vanish.js';
import {isLadyMessage} from './fountain-lady.js';
import {glowAlignment} from './altar-glow.js';
import {strikeVictim} from './mjollnir-storm.js';
import {confirmsPlayerMelee} from './combat-visuals.js';
import {enqueueAction} from './actions.js';
import {addMessage,panelView} from './message-log.js';

export function message(text,L){const {bagExplosion,splash,S,heldUnder,groundItems,release,actors,digChips,hero,digCracks,digSwing,prayerKneel,digDrop,stairTumble,levelUp,prayerLight,throneVanish,fountainLady,fountainSnakes,fountainGush,altarSacrifice,altarClover,altarFlashes,STRIKE_PAIR_MS,queueStrike,altarGift,blessFlash,glowLog,fountainNymph,fountainDemon,fountainWish,fireTrapJet,monsterSquare,goldGlint,firstKill,potionSip,sinkDrain,stoneCure,towelWipe,calmClear,unicornSpiral,searchReveal,squeakyBoard,rollingTrap,fallingRock,dartTrap,landMine,rustTrap,iceTrap,pitFall,polyTrap,magicTrap,boulderFill,spellFizzle,throneSit,throneCurse,throneInsight,throneWrench,throneGift,spellStudy,spellCrumble,antiMagic,webSnare,statueTrap,bearTrapSnap,sleepingGas,teleportBlink,magicPortal,grab,brainSuck,poly,barsMelt,breath,messageLog,drawMessagePanels}=L;splash.queueMessage(text);{const seen=/^You (?:see|feel) here (.+)\.$/.exec(text);if(seen)S.groundPriced=[seen[1]];}{const taker=takerOf(text);if(taker)for(const id of takenSquares(taker,heldUnder.map)){for(const k of heldUnder.map.get(id).keys){const it=groundItems.get(k);if(it){release(it);groundItems.delete(k);}}heldUnder.map.delete(id);}}/* a monster that picks up or eats what it stands on takes it (held-items.js) *//* a pet cat the game says is eating crouches over its food and chews (feline-skin.js eat) */if(petEats(text))for(const a of actors.values())if(a.petCat&&a.animator?.eat)a.animator.eat();if(S.latest?.player){digChips.message(text,S.latest.player.x-S.origin.x,S.latest.player.z-S.origin.z,hero.g.rotation.y);digCracks.message(text,S.latest.player.x-S.origin.x,S.latest.player.z-S.origin.z,hero.g.rotation.y);digSwing.message(text);prayerKneel.message(text);digDrop.message(text,S.airborne);stairTumble.message(text);levelUp.message(text,S.latest.player.x-S.origin.x,S.latest.player.z-S.origin.z);prayerLight.message(text,S.latest.player.x-S.origin.x,S.latest.player.z-S.origin.z);bagExplosion.message(text,S.latest.player.x-S.origin.x,S.latest.player.z-S.origin.z);}if(isThronePuff(text)&&S.latest?.player)throneVanish.add(S.latest.player.x-S.origin.x,S.latest.player.z-S.origin.z,S.latest.player.x*7+S.latest.player.z);if(isLadyMessage(text)&&S.latest?.player)fountainLady.add(S.latest.player.x-S.origin.x,S.latest.player.z-S.origin.z);if(S.latest?.player){fountainLady.message(text,S.latest.player.x-S.origin.x,S.latest.player.z-S.origin.z);fountainSnakes.message(text,S.latest.player.x-S.origin.x,S.latest.player.z-S.origin.z);fountainGush.message(text,S.latest.player.x-S.origin.x,S.latest.player.z-S.origin.z);altarSacrifice.message(text,S.latest.player.x-S.origin.x,S.latest.player.z-S.origin.z);altarClover.message(text,S.latest.player.x-S.origin.x,S.latest.player.z-S.origin.z);if(glowAlignment(text))S.pendingAltarGlow=text;altarFlashes.message(text,S.latest.player.x-S.origin.x,S.latest.player.z-S.origin.z);{const victim=strikeVictim(text);if(victim){const now=performance.now();if(S.lastHeroHit&&now-S.lastHeroHit.t<STRIKE_PAIR_MS){queueStrike(S.lastHeroHit);S.lastHeroHit=null;}else S.pendingStrike={name:victim,t:now};}};altarGift.message(text,S.latest.player.x-S.origin.x,S.latest.player.z-S.origin.z);blessFlash.message(text,S.latest.player.x-S.origin.x,S.latest.player.z-S.origin.z);glowLog.note(text,performance.now());fountainNymph.message(text,S.latest.player.x-S.origin.x,S.latest.player.z-S.origin.z,hero.g.rotation.y);fountainDemon.message(text,S.latest.player.x-S.origin.x,S.latest.player.z-S.origin.z);fountainWish.message(text,S.latest.player.x-S.origin.x,S.latest.player.z-S.origin.z);fireTrapJet.message(text,S.latest.player.x-S.origin.x,S.latest.player.z-S.origin.z,monsterSquare);goldGlint.message(text,S.latest.player.x-S.origin.x,S.latest.player.z-S.origin.z);firstKill.message(text,S.latest.player.x-S.origin.x,S.latest.player.z-S.origin.z);potionSip.message(text,S.latest.player.x-S.origin.x,S.latest.player.z-S.origin.z);sinkDrain.message(text,S.latest.player.x-S.origin.x,S.latest.player.z-S.origin.z);stoneCure.message(text,S.latest.player.x-S.origin.x,S.latest.player.z-S.origin.z);towelWipe.message(text,S.latest.player.x-S.origin.x,S.latest.player.z-S.origin.z);calmClear.message(text,S.latest.player.x-S.origin.x,S.latest.player.z-S.origin.z);unicornSpiral.message(text,S.latest.player.x-S.origin.x,S.latest.player.z-S.origin.z);searchReveal.message(text,S.latest.player.x-S.origin.x,S.latest.player.z-S.origin.z);squeakyBoard.message(text,S.latest.player.x-S.origin.x,S.latest.player.z-S.origin.z);rollingTrap.message(text,S.latest.player.x-S.origin.x,S.latest.player.z-S.origin.z);fallingRock.message(text,S.latest.player.x-S.origin.x,S.latest.player.z-S.origin.z);dartTrap.message(text,S.latest.player.x-S.origin.x,S.latest.player.z-S.origin.z,hero.g.rotation.y);landMine.message(text,S.latest.player.x-S.origin.x,S.latest.player.z-S.origin.z,name=>{let best=null;for(const a of actors.values())if(a.species===name&&a.target&&!a.actions?.dead){const d=a.target.distanceTo(hero.g.position);if(!best||d<best.d)best={d,p:a.target};}return best?.p||null;});/* a monster's land mine goes off where it is (land-mine.js) */rustTrap.message(text,S.latest.player.x-S.origin.x,S.latest.player.z-S.origin.z,hero.g.rotation.y);iceTrap.message(text,S.latest.player.x-S.origin.x,S.latest.player.z-S.origin.z);pitFall.message(text,S.latest.player.x-S.origin.x,S.latest.player.z-S.origin.z);polyTrap.message(text,S.latest.player.x-S.origin.x,S.latest.player.z-S.origin.z);magicTrap.message(text,S.latest.player.x-S.origin.x,S.latest.player.z-S.origin.z);boulderFill.message(text,S.latest.player.x-S.origin.x,S.latest.player.z-S.origin.z,hero.g.rotation.y);spellFizzle.message(text,S.latest.player.x-S.origin.x,S.latest.player.z-S.origin.z);throneSit.message(text,S.latest.player.x-S.origin.x,S.latest.player.z-S.origin.z);throneCurse.message(text,S.latest.player.x-S.origin.x,S.latest.player.z-S.origin.z);throneInsight.message(text,S.latest.player.x-S.origin.x,S.latest.player.z-S.origin.z);throneWrench.message(text,S.latest.player.x-S.origin.x,S.latest.player.z-S.origin.z);throneGift.message(text,S.latest.player.x-S.origin.x,S.latest.player.z-S.origin.z);spellStudy.message(text,S.latest.player.x-S.origin.x,S.latest.player.z-S.origin.z);spellCrumble.message(text,S.latest.player.x-S.origin.x,S.latest.player.z-S.origin.z);antiMagic.message(text,S.latest.player.x-S.origin.x,S.latest.player.z-S.origin.z);webSnare.message(text,S.latest.player.x-S.origin.x,S.latest.player.z-S.origin.z);statueTrap.message(text,S.latest.player.x-S.origin.x,S.latest.player.z-S.origin.z);bearTrapSnap.message(text,S.latest.player.x-S.origin.x,S.latest.player.z-S.origin.z);sleepingGas.message(text,S.latest.player.x-S.origin.x,S.latest.player.z-S.origin.z);teleportBlink.message(text,S.latest.player.x-S.origin.x,S.latest.player.z-S.origin.z);magicPortal.message(text,S.latest.player.x-S.origin.x,S.latest.player.z-S.origin.z);}grab.message(text,S.latest);brainSuck.message(text,S.latest);poly.message(text);barsMelt.message(text);breath.message(text);if(!S.combatStream&&S.meleeIntent&&confirmsPlayerMelee(text)){enqueueAction(hero.actions,{kind:'attack',attack:'weapon',result:'hit',dir:S.meleeIntent});S.meleeIntent=null;}addMessage(messageLog,text);S.lastMessageText=text;/* a burst of messages (a fight, a long --More-- run) redraws the panels once, on the next frame */if(!S.messagePanelsDue){S.messagePanelsDue=true;requestAnimationFrame(drawMessagePanels);}}
export function drawMessagePanels(L){const {S,$,messageLog,historyPanel}=L;S.messagePanelsDue=false;const line=$('#engine-line'),log=$('#engine-messages');const view=panelView(messageLog);log.replaceChildren(...view.earlier.map((t,i)=>{const p=document.createElement('div');p.textContent=t;p.className=`msg msg-${view.earlierTones[i]}`;return p;}));log.scrollTop=0;line.textContent=view.line;line.className=`msg msg-${view.lineTone}`;$('#message').textContent=S.lastMessageText;historyPanel.refresh();}
